.rows.forEach(function(r){var s=r.status==='approved'?(fill?'Đã duyệt lấp tiết':'Đã duyệt'):(r.status==='rejected'?'Từ chối':'Chờ duyệt'),tr=document.createElement('tr'),teacher=esc(r.substitute_teacher);if(fill){var options='<option value="">Chọn môn lấp tiết...</option>';(r.fill_subjects||[]).forEach(function(subject){var selected=r.kind==='fill'&&r.subject===subject?' selected':'';options+='<option value="'+esc(subject)+'"'+selected+'>'+esc(subject)+'</option>';});teacher+='<select class="form-select form-select-sm mt-1 tkb-fill-subject" data-id="'+esc(r.id)+'">'+options+'</select>';}tr.innerHTML='<td><input class="form-check-input tkb-sub-check" type="checkbox" value="'+esc(r.id)+'"></td><td>'+vnDate(r.date)+'</td><td><strong>'+esc(r.absent_teacher)+'</strong></td><td>'+esc(r.session)+' '+r.period+' · '+esc(r.class)+' · '+esc(r.original_subject||r.subject)+'</td><td>'+teacher+'</td><td class="tkb-status-'+esc(r.status)+'">'+s+'</td>';body.appendChild(tr);});manageSection.querySelectorAll('[data-scope]').forEach(function(b){b.onclick=function(){var d=(manageSection.querySelector('#tkbManageDate')||{}).value||requestedDate;loadManage(this.dataset.scope,d);};});manageSection.querySelector('#tkbSelectAll').onchange=function(){var x=this.checked;manageSection.querySelectorAll('.tkb-sub-check').forEach(function(c){c.checked=x;});};var ap=manageSection.querySelector('#tkbApproveMany');if(ap)ap.onclick=function(){bulk('approve_many');};var del=manageSection.querySelector('#tkbDeleteMany');if(del)del.onclick=function(){bulk('delete_many');};manageSection.querySelector('#tkbShareSubs').onclick=function(){tkbShareImage(manageSection.querySelector('.table-responsive'),fill?'LỊCH LẤP TIẾT':'LỊCH DẠY THAY',vnDate(data.from)+' – '+vnDate(data.to),fill?'lich-lap-tiet.png':'lich-day-thay.png');};}
 function renderUnifiedManage(data){manageData=data;if(manageSection)manageSection.remove();manageSection=document.createElement('section');manageSection.className='tkb-manage-anchor';manageSection.innerHTML='<div class="tkb-card p-3 mb-3"><div class="d-flex justify-content-between gap-2 flex-wrap align-items-center mb-2"><div><h4 class="mb-1"><i class="bi bi-clipboard2-check me-1"></i> Quản lý dạy thay - bù</h4><div class="small text-muted">Duyệt tập trung đăng ký dạy thay, lấp tiết và dạy bù · '+vnDate(data.from)+' – '+vnDate(data.to)+'</div></div><div class="d-flex gap-2"><button class="btn btn-sm btn-outline-primary" data-scope="today">Hôm nay</button><button class="btn btn-sm btn-primary" data-scope="week">Cả tuần</button></div></div><div class="tkb-manage-toolbar d-flex gap-2 flex-wrap align-items-center"><input type="date" class="form-control form-control-sm" id="tkbManageDate" style="max-width:170px" value="'+(requestedDate||data.from||'')+'"><button class="btn btn-sm btn-success" id="tkbApproveMany"><i class="bi bi-check2-circle"></i> Duyệt đã chọn</button><button class="btn btn-sm btn-danger" id="tkbDeleteMany"><i class="bi bi-trash"></i> Xóa đã chọn</button></div></div>';var host=manageHost();if(host.id==='tkbUnifiedManageHost')host.appendChild(manageSection);else host.insertAdjacentElement('afterend',manageSection);var groups=[['substitution','Dạy thay','primary'],['fill','Lấp tiết','warning'],['makeup','Dạy bù','success']];groups.forEach(function(group){var rows=data.rows.filter(function(r){return r.kind===group[0];}),card=document.createElement('div');card.className='tkb-card p-3 mb-3';card.innerHTML='<h5 class="mb-2 text-'+group[2]+'">'+group[1]+' <span class="badge text-bg-light">'+rows.length+'</span></h5><div class="table-responsive"><table class="table table-sm align-middle mb-0 tkb-manage-table"><thead><tr><th style="width:36px"><input type="checkbox" class="tkb-group-all"></th><th>Ngày</th><th>Buổi/Tiết · Lớp</th><th>Môn</th><th>Giáo viên</th><th>Trạng thái</th></tr></thead><tbody></tbody></table></div>';var body=card.querySelector('tbody');if(!rows.length)body.innerHTML='<tr><td colspan="6" class="text-center text-muted py-3">Không có đăng ký '+group[1].toLowerCase()+' trong phạm vi này.</td></tr>';rows.forEach(function(r){var tr=document.createElement('tr'),status=r.status==='approved'?'Đã duyệt':(r.status==='rejected'?'Từ chối':'Chờ duyệt'),subjects='';if(r.kind==='fill'){subjects='<div class="small text-muted">Môn nghỉ: '+esc(r.original_subject||r.subject)+'</div><select class="form-select form-select-sm mt-1 tkb-fill-subject" data-id="'+esc(r.id)+'"><option value="">Chọn môn lấp tiết...</option>';(r.fill_subjects||[]).forEach(function(s){subjects+='<option value="'+esc(s)+'" '+(r.status==='approved'&&r.subject===s?'selected':'')+'>'+esc(s)+'</option>';});subjects+='</select>';}else subjects='<strong>'+esc(r.subject)+'</strong>';var people=r.kind==='makeup'?'<strong>'+esc(r.substitute_teacher)+'</strong>':'<span>'+esc(r.absent_teacher)+'</span> → <strong>'+esc(r.substitute_teacher)+'</strong>';tr.innerHTML='<td><input class="form-check-input tkb-sub-check" type="checkbox" value="'+esc(r.id)+'" data-kind="'+esc(r.kind)+'"></td><td>'+vnDate(r.date)+'</td><td>'+esc(r.session)+' '+r.period+' · <strong>'+esc(r.class)+'</strong></td><td>'+subjects+'</td><td>'+people+'</td><td class="tkb-status-'+esc(r.status)+'">'+status+'</td>';body.appendChild(tr);});card.querySelector('.tkb-group-all').onchange=function(){var checked=this.checked;card.querySelectorAll('.tkb-sub-check').forEach(function(c){c.checked=checked;});};manageSection.appendChild(card);});manageSection.querySelectorAll('[data-scope]').forEach(function(b){b.onclick=function(){loadManage(this.dataset.scope,(manageSection.querySelector('#tkbManageDate')||{}).value||requestedDate);};});manageSection.querySelector('#tkbApproveMany').onclick=function(){bulk('approve_many');};manageSection.querySelector('#tkbDeleteMany').onclick=function(){bulk('delete_many');};}
 function installSummaryControls(data){var bar=manageSection&&manageSection.querySelector('.tkb-manage-toolbar');if(!bar||bar.querySelector('#tkbExportCombined'))return;var box=document.createElement('div');box.className='d-flex gap-2 flex-wrap align-items-end ms-auto';box.innerHTML='<label class="small fw-bold">Từ ngày<input type="date" class="form-control form-control-sm mt-1" id="tkbSummaryFrom" value="'+esc(data.from||'')+'"></label><label class="small fw-bold">Đến ngày<input type="date" class="form-control form-control-sm mt-1" id="tkbSummaryTo" value="'+esc(data.to||'')+'"></label><button type="button" class="btn btn-sm btn-outline-success mb-0" id="tkbExportCombined"><i class="bi bi-image"></i> Xuất ảnh lịch chung</button>';bar.appendChild(box);box.querySelector('#tkbExportCombined').onclick=exportCombinedSchedule;}
 function exportCombinedSchedule(){var from=(document.getElementById('tkbSummaryFrom')||{}).value,to=(document.getElementById('tkbSummaryTo')||{}).value;if(!from||!to){alert('Hãy chọn đủ từ ngày và đến ngày.');return;}var button=document.getElementById('tkbExportCombined');if(button)button.disabled=true;var url=manageEndpoint+'?mode=all&scope=range&from='+encodeURIComponent(from)+'&to='+encodeURIComponent(to)+'&date='+encodeURIComponent(from);fetch(url,{credentials:'same-origin'}).then(function(r){return r.json();}).then(function(data){if(!data.rows||!data.rows.length){alert('Không có lịch dạy thay, dạy bù hoặc lấp tiết trong khoảng đã chọn.');return;}var view=buildCombinedSchedule(data.rows);document.body.appendChild(view);return tkbShareImage(view,'LỊCH DẠY THAY – DẠY BÙ – LẤP TIẾT',vnDate(data.from)+' – '+vnDate(data.to),'lich-day-thay-day-bu-lap-tiet.png').finally(function(){view.remove();});}).catch(function(){alert('Không tạo được lịch tổng hợp.');}).finally(function(){if(button)button.disabled=false;});}
 function buildCombinedSchedule(rows){var labels={substitution:'DẠY THAY',makeup:'DẠY BÙ',fill:'LẤP TIẾT'},order=['substitution','makeup','fill'],wrap=document.createElement('div');wrap.className='tkb-summary';order.forEach(function(kind){var list=rows.filter(function(r){return r.kind===kind;});if(!list.length)return;list.sort(function(a,b){return a.date.localeCompare(b.date)||(sessionRank(a.session)-sessionRank(b.session))||a.period-b.period||a.class.localeCompare(b.class);});var table=document.createElement('table');table.className='mb-4';table.innerHTML='<thead><tr class="sum-type type-'+kind+'"><th colspan="9">'+labels[kind]+' ('+list.length+' tiết)</th></tr><tr><th>Ngày</th><th>Buổi</th><th>Tiết</th><th>Lớp</th><th>Môn nghỉ</th><th>Giáo viên nghỉ</th><th>'+(kind==='fill'?'Môn lấp tiết':(kind==='makeup'?'Môn dạy bù':'Môn dạy'))+'</th><th>Giáo viên dạy</th><th>Trạng thái</th></tr></thead><tbody></tbody>';var body=table.querySelector('tbody'),dateCounts={},sessionCounts={};list.forEach(function(r){dateCounts[r.date]=(dateCounts[r.date]||0)+1;var sk=r.date+'|'+r.session;sessionCounts[sk]=(sessionCounts[sk]||0)+1;});var seenDate={},seenSession={};list.forEach(function(r){var tr=document.createElement('tr'),dateCell='',sessionCell='',sk=r.date+'|'+r.session;if(!seenDate[r.date]){seenDate[r.date]=true;dateCell='<td rowspan="'+dateCounts[r.date]+'" class="sum-date">'+vnDate(r.date)+'</td>';}if(!seenSession[sk]){seenSession[sk]=true;var afternoon=sessionRank(r.session)===1;sessionCell='<td rowspan="'+sessionCounts[sk]+'" class="sum-session '+(afternoon?'session-afternoon':'session-morning')+'">'+esc(r.session)+'</td>';}var status=r.status==='approved'?'Đã duyệt':(r.status==='rejected'?'Từ chối':'Chờ duyệt'),taughtSubject=r.subject||'',absentSubject=kind==='makeup'?'—':(r.original_subject||r.subject||'—'),absentTeacher=kind==='makeup'?'—':(r.absent_teacher||'—');tr.innerHTML=dateCell+sessionCell+'<td class="sum-period">'+r.period+'</td><td><strong>'+esc(r.class)+'</strong></td><td class="sum-subject">'+esc(absentSubject)+'</td><td>'+esc(absentTeacher)+'</td><td class="sum-subject">'+esc(taughtSubject)+'</td><td><strong>'+esc(r.substitute_teacher||'')+'</strong></td><td class="sum-status tkb-status-'+esc(r.status)+'">'+status+'</td>';body.appendChild(tr);});wrap.appendChild(table);});var note=document.createElement('div');note.className='tkb-summary-note';note.innerHTML='<i class="bi bi-info-circle-fill"></i> Ghi chú: Giáo viên được phân công chủ động thực hiện theo lịch, báo cho học sinh chuẩn bị tiết học.';wrap.appendChild(note);return wrap;}
 function sessionRank(value){return /chi(e|ề)u|pm/i.test(String(value||''))?1:0;}
 function bulk(action){var checks=Array.from(manageSection.querySelectorAll('.tkb-sub-check:checked')),ids=checks.map(function(c){return c.value;});if(!ids.length){alert('Hãy chọn ít nhất một lịch.');return;}var b=new URLSearchParams();b.set('action',action);b.set('mode',currentMode==='manage'?'all':currentMode);b.set('csrf',manageData.csrf);if(action==='approve_many'){for(var i=0;i<checks.length;i++){if(checks[i].dataset.kind!=='fill')continue;var select=manageSection.querySelector('.tkb-fill-subject[data-id="'+CSS.escape(ids[i])+'"]');if(!select||!select.value){alert('Hãy chọn môn lấp tiết cho tất cả đăng ký lấp tiết cần duyệt.');return;}b.set('fill_subjects['+ids[i]+']',select.value);}}var verb=action==='approve_many'?'duyệt':'xóa';if(!confirm('Bạn có chắc muốn '+verb+' '+ids.length+' lịch đã chọn?'))return;ids.forEach(function(id){b.append('ids[]',id);});fetch(manageEndpoint,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:b.toString()}).then(function(r){return r.json();}).then(function(x){alert(x.message||'Đã xử lý.');if(x.ok)loadManage(manageData.scope,requestedDate);});}
 loadManage('week',requestedDate);
 function vnDate(v){if(!v)return'';var p=v.split('-');return p.length===3?p[2]+'/'+p[1]+'/'+p[0]:v;}function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c];});}
})();
</script>
