<script>
async function tkbShareImage(target,mainTitle,subTitle,fileName){if(!target||typeof html2canvas==='undefined'){alert('Chưa tải được bộ tạo ảnh.');return;}var stage=document.createElement('div');stage.style.cssText='position:fixed;left:-10000px;top:0;width:1200px;background:#fff;padding:34px;font-family:Arial,sans-serif;color:#172033;z-index:-1';var head=document.createElement('div');head.style.cssText='text-align:center;margin-bottom:20px';head.innerHTML='<div style="font-size:19px;font-weight:400;text-transform:uppercase"><?=htmlspecialchars($tkbSo,ENT_QUOTES,'UTF-8')?></div><div id="tkb-share-school" style="display:inline-block;font-size:22px;font-weight:800;text-transform:uppercase;margin-top:5px;padding:0 18px 13px;position:relative"><?=htmlspecialchars($tkbSchool,ENT_QUOTES,'UTF-8')?><div style="position:absolute;left:16.666%;right:16.666%;bottom:0;height:2px;background:#1f5d8d"></div></div><div style="font-size:29px;font-weight:900;color:#164e73;margin-top:20px">'+escapeHtml(mainTitle)+'</div><div style="font-size:18px;font-weight:700;margin-top:7px;color:#475569">'+escapeHtml(subTitle||'')+'</div>';var clone=target.cloneNode(true);clone.style.width='100%';clone.style.maxWidth='none';clone.style.overflow='visible';clone.querySelectorAll('button,input[type="checkbox"],select').forEach(function(x){if(x.tagName==='SELECT'){var s=document.createElement('span');s.textContent=x.options[x.selectedIndex]?x.options[x.selectedIndex].textContent:'';x.replaceWith(s);}else x.remove();});clone.querySelectorAll('.session-name').forEach(function(el){var txt=(el.textContent||'').trim().toUpperCase();el.style.background=txt==='C'?'#dcfce7':'#fff2b8';el.style.color=txt==='C'?'#166534':'#6b4d00';});stage.append(head,clone);document.body.appendChild(stage);try{var canvas=await html2canvas(stage,{scale:1.6,backgroundColor:'#ffffff',useCORS:true});canvas.toBlob(async function(blob){stage.remove();if(!blob)return;var file=new File([blob],fileName||'thoi-khoa-bieu.png',{type:'image/png'});if(navigator.canShare&&navigator.canShare({files:[file]})){try{await navigator.share({files:[file],title:mainTitle,text:subTitle||''});return;}catch(e){}}var a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=file.name;a.click();setTimeout(function(){URL.revokeObjectURL(a.href);},1500);},'image/png');}catch(e){stage.remove();alert('Không tạo được ảnh chia sẻ.');}}
function escapeHtml(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c];});}
</script>
